use core::sync::atomic::{AtomicU32 as A,Ordering as O};fn one(s:O,f:O){let a=A::new(7);match a.compare_exchange_weak(7,9,s,f){Ok(old)=>{check(old==7);check(a.load(O::SeqCst)==9);},Err(actual)=>{check(actual==7);check(a.load(O::SeqCst)==7);}}let value=a.load(O::SeqCst);match a.compare_exchange_weak(0,13,s,f){Ok(_)=>check(false),Err(actual)=>check(actual==value)}check(a.load(O::SeqCst)==value);}fn main(){one(O::Relaxed,O::Relaxed);one(O::Relaxed,O::Acquire);one(O::Relaxed,O::SeqCst);one(O::Release,O::Relaxed);one(O::Release,O::Acquire);one(O::Release,O::SeqCst);one(O::Acquire,O::Relaxed);one(O::Acquire,O::Acquire);one(O::Acquire,O::SeqCst);one(O::AcqRel,O::Relaxed);one(O::AcqRel,O::Acquire);one(O::AcqRel,O::SeqCst);one(O::SeqCst,O::Relaxed);one(O::SeqCst,O::Acquire);one(O::SeqCst,O::SeqCst);}
